package com.jadhavr.erp.fee.repository; import com.jadhavr.erp.fee.entity.FeePayment; import com.jadhavr.erp.fee.enums.PaymentStatus; import org.springframework.data.jpa.repository.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.List; public interface FeePaymentRepository extends JpaRepository<FeePayment,Long>,JpaSpecificationExecutor<FeePayment>{List<FeePayment> findByStudentUserIdOrderByCreatedAtDesc(Long id); List<FeePayment> findByStudentFeeAccountIdOrderByCreatedAtDesc(Long id); boolean existsByCollegeIdAndTransactionReferenceIgnoreCase(Long id,String ref); long countByCollegeIdAndStatus(Long id,PaymentStatus s); long countByStatus(PaymentStatus s); @Query("select coalesce(sum(p.amount),0) from FeePayment p where p.college.id=:c and p.status=:s") BigDecimal sumByCollegeAndStatus(Long c,PaymentStatus s); @Query("select coalesce(sum(p.amount),0) from FeePayment p where p.status=:s") BigDecimal sumByStatus(PaymentStatus s); @Query("select coalesce(sum(p.amount),0) from FeePayment p where p.college.id=:c and p.status='VERIFIED' and p.verifiedAt>=:start") BigDecimal sumToday(Long c,LocalDateTime start); @Query("select coalesce(sum(p.amount),0) from FeePayment p where p.status='VERIFIED' and p.verifiedAt>=:start") BigDecimal sumTodayAll(LocalDateTime start);}
